template<class T, class CharT = char, class Traits = std::char_traits<CharT>, class Distance = std::ptrdiff_t>
class std::istream_iterator;

// Usage example with implementation notes:
std::istream_iterator<int> iter(std::cin);  // Constructs an iterator that may read the first int from std::cin at runtime. The compiler instantiates the template for T=int, potentially inlining some operators if optimized.
*iter;  // Dereferences to read and return the value, invoking std::cin >> value; at runtime, with assembly involving call to extraction operator.
++iter;  // Advances by reading the next value, non-const and single-pass due to stream nature.

code_example:
#include <iostream>
#include <iterator>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> numbers;
    std::copy(
        std::istream_iterator<int>(std::cin),  // Begin iterator: reads from std::cin
        std::istream_iterator<int>(),          // End iterator: default-constructed, represents end-of-stream
        std::back_inserter(numbers)            // Output iterator to insert into vector
    );
    for (const auto& num : numbers) {
        std::cout << num << ' ';  // Output the read numbers
    }
    std::cout << std::endl;
    return 0;
}
